/* "cover": the picture layer is 30% taller than the frame and travels from -15% to +15% of the
   frame while the frame crosses the window, so it moves slower than the page.
   "exit": for a frame at the very top of the page; the picture sinks by a third of the frame
   while the frame leaves the window (it seems to stay behind). */
.esrbespoke-parallax {
  view-timeline: --esrbespoke-parallax block;
}
.esrbespoke-parallax-layer[data-drift="cover"] {
  top: -15%;
  bottom: -15%;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .esrbespoke-parallax-layer[data-drift="cover"] {
      animation: esrbespoke-parallax-cover linear both;
      animation-timeline: --esrbespoke-parallax;
      animation-range: cover 0% cover 100%;
    }
    .esrbespoke-parallax-layer[data-drift="exit"] {
      animation: esrbespoke-parallax-exit linear both;
      animation-timeline: --esrbespoke-parallax;
      animation-range: exit 0% exit 100%;
    }
    .esrbespoke-parallax[data-fade] .esrbespoke-parallax-fade {
      animation: esrbespoke-parallax-fade linear both;
      animation-timeline: --esrbespoke-parallax;
      animation-range: entry 0% cover 35%;
    }
  }
}

@media (prefers-reduced-motion: no-preference) {
  .esrbespoke-parallax[data-rise] {
    animation: esrbespoke-parallax-rise 1.2s cubic-bezier(0.19, 1, 0.22, 1) 0.15s both;
  }
}

@keyframes esrbespoke-parallax-cover {
  from { transform: translateY(-11.5%); }
  to { transform: translateY(11.5%); }
}
@keyframes esrbespoke-parallax-exit {
  from { transform: translateY(0); }
  to { transform: translateY(33%); }
}
@keyframes esrbespoke-parallax-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes esrbespoke-parallax-rise {
  from { transform: translateY(1rem); }
  to { transform: translateY(0); }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./esrbespoke-parallax.css";

export interface EsrbespokeParallaxProps {
  /** the picture or video; it should fill its box (`h-full w-full object-cover`). Empty: a placeholder */
  media?: ReactNode;
  /** how the picture drifts: "cover" while the frame crosses the window, "exit" for a frame at the page top, "none" */
  drift?: "cover" | "exit" | "none";
  /** fade the picture in as the frame enters the window */
  fadeIn?: boolean;
  /** rise 16px into place on page load (the inner pages' hero photo) */
  rise?: boolean;
  /** sizes the frame: h-svh, aspect-[4/3], … */
  className?: string;
  /** classes for the placeholder surface when there is no media */
  placeholderClassName?: string;
}

/** A cropped media frame with a scrubbed parallax drift; a plain muted surface when empty. */
export function EsrbespokeParallax({ media, drift = "cover", fadeIn = false, rise = false, className, placeholderClassName }: EsrbespokeParallaxProps) {
  return (
    <div
      className={cn("esrbespoke-parallax relative overflow-clip bg-background", className)}
      data-fade={fadeIn || undefined}
      data-rise={rise || undefined}
    >
      <div className="esrbespoke-parallax-layer absolute inset-0" data-drift={drift}>
        <div className="esrbespoke-parallax-fade h-full w-full [&>*]:h-full [&>*]:w-full [&>img]:object-cover [&>video]:object-cover">
          {media ?? <div aria-hidden className={cn("h-full w-full bg-muted", placeholderClassName)} />}
        </div>
      </div>
    </div>
  );
}
